<?php require 'config.php'; need();if(user()['role']=='chp'){header('Location: chp.php');exit;}
head('Home');
$q=function($sql,$a=[])use($pdo){try{$s=$pdo->prepare($sql);$s->execute($a);return $s->fetchAll();}catch(Exception $x){return [];}};
$one=function($sql)use($q){$r=$q($sql);return $r?(int)array_values($r[0])[0]:0;};
$days=[];for($i=6;$i>=0;$i--)$days[date('Y-m-d',strtotime("-$i day"))]=date('D',strtotime("-$i day"));$z=array_fill_keys(array_keys($days),0);
$enc=$z;foreach($q('SELECT DATE(created_at) d,COUNT(*) n FROM visits WHERE created_at>=CURDATE()-INTERVAL 6 DAY GROUP BY DATE(created_at)') as $r)$enc[$r['d']]=(int)$r['n'];
$prev=$one('SELECT COUNT(*) FROM visits WHERE created_at>=CURDATE()-INTERVAL 13 DAY AND created_at<CURDATE()-INTERVAL 6 DAY');$cur=array_sum($enc);$chg=$prev?round(($cur-$prev)/$prev*100):($cur?100:0);
$col=['cash'=>$z,'mpesa'=>$z,'bank'=>$z];foreach($q('SELECT DATE(created_at) d,method,SUM(amount) s FROM payments WHERE created_at>=CURDATE()-INTERVAL 6 DAY GROUP BY DATE(created_at),method') as $r)if(isset($col[$r['method']][$r['d']]))$col[$r['method']][$r['d']]=(float)$r['s'];
$all=$z;foreach($col as $mm)foreach($mm as $d=>$v)$all[$d]+=$v;$col['all']=$all;
$dx=['u'=>[],'o'=>[]];foreach(['u'=>'<5','o'=>'>=5'] as $k=>$cmp)foreach($q("SELECT c.diagnosis dg,COUNT(*) n FROM consultations c JOIN visits v ON v.id=c.visit_id JOIN patients p ON p.id=v.patient_id WHERE TIMESTAMPDIFF(YEAR,p.dob,c.created_at)$cmp GROUP BY c.diagnosis ORDER BY n DESC LIMIT 5") as $r)$dx[$k][]=[$r['dg'],(int)$r['n']];
$lab=array_column($q('SELECT status,COUNT(*) n FROM lab_orders GROUP BY status'),'n','status');$rx=array_column($q('SELECT status,COUNT(*) n FROM prescriptions GROUP BY status'),'n','status');
$lt=array_sum($lab);$rt=array_sum($rx);$inp=$one('SELECT COUNT(*) FROM admissions WHERE discharged_at IS NULL');$beds=$one('SELECT COUNT(*) FROM beds')-$inp;
$wait=$one("SELECT COUNT(*) FROM visits WHERE status<>'done' AND DATE(created_at)=CURDATE()");$unp=$one("SELECT COUNT(*) FROM invoices WHERE status<>'paid'");$nbu=$one("SELECT COUNT(*) FROM nbu_admissions WHERE status='admitted'");
$row=function($l,$n,$t,$c){$p=$t?round($n/$t*100,1):0;return '<div style="display:flex;justify-content:space-between;font-size:13px"><span>'.$l.' ('.$n.'/'.$t.')</span><span>'.$p.'%</span></div><div class=pb><i data-w="'.$p.'" style="width:0;background:'.$c.'"></i></div>';};
$img=array_column($q('SELECT status,COUNT(*) n FROM imaging_orders GROUP BY status'),'n','status');$prc=array_column($q('SELECT status,COUNT(*) n FROM procedure_orders GROUP BY status'),'n','status');$it=array_sum($img);$pt2=array_sum($prc);
$h=(int)date('G');?>
<style>.dg{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:14px;margin-bottom:16px}.wd{background:linear-gradient(150deg,#12303d,#0a1c27);color:#e8f4f4;border-radius:14px;padding:16px;box-shadow:0 4px 18px rgba(0,0,0,.25)}.wd h4{margin:0 0 6px;font-size:13px;letter-spacing:1px;color:#8fd3df}.big{font-size:34px;font-weight:700}.pos{color:#4ade80;font-size:14px}.neg{color:#f87171;font-size:14px}.wd select{width:auto;background:#1f4152;color:#fff;border:0;padding:4px 8px;float:right}
.bc{display:flex;align-items:flex-end;gap:10px;height:150px;margin-top:10px}.bc>div{flex:1;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;height:100%}.bar{width:100%;border-radius:5px 5px 0 0;background:linear-gradient(#22d3ee,#0891b2);height:0;transition:height 1s cubic-bezier(.2,.8,.2,1)}.gold{background:repeating-linear-gradient(#fcd34d 0 8px,#d9a416 8px 10px)}.bc small{font-size:11px;color:#9fb8bd;margin-top:4px}
.pb{height:7px;background:#243a46;border-radius:4px;margin:3px 0 10px}.pb i{display:block;height:100%;border-radius:4px;transition:width 1s}.dxr{display:flex;justify-content:space-between;padding:8px 10px;margin:6px 0;background:rgba(255,255,255,.06);border-radius:8px;font-size:13px}.chip{background:#b91c1c;border-radius:12px;padding:1px 10px;font-size:12px;white-space:nowrap}</style>
<p style="margin:0 0 12px"><?=$h<12?'Good morning':($h<17?'Good afternoon':'Good evening')?>, <?=e(user()['name'])?>.</p>
<div class=dg>
<div class=wd><h4>ENCOUNTERS</h4><span class=big data-n="<?=$cur?>">0</span> <span class="<?=$chg>=0?'pos':'neg'?>"><?=$chg>=0?'&uarr;':'&darr;'?> <?=abs($chg)?>%<?=$chg>=100?'+':''?></span><div class=bc id=eb></div><small style="color:#8fd3df">Past 7 days</small></div>
<div class=wd><h4>DIAGNOSES</h4><select id=dxs><option value=o>Over 5<option value=u>Under 5</select><div id=dxl style="margin-top:34px"></div></div>
<div class=wd><h4>COLLECTIONS</h4><select id=cls><option value=all>All<option value=cash>Cash<option value=mpesa>M-Pesa<option value=bank>Bank</select><div class=big id=ct style="margin-top:6px">0</div><div class=bc id=cb></div><small style="color:#8fd3df">Past 7 days (KES)</small></div>
<div class=wd><h4>LAB TESTS</h4><span class=big data-n="<?=$lt?>">0</span><div style="margin-top:12px"><?=$row('Completed',(int)($lab['done']??0),$lt,'#f472b6')?><?=$row('Queued',(int)($lab['pending']??0),$lt,'#fbbf24')?></div></div>
<div class=wd><h4>PRESCRIPTIONS</h4><span class=big data-n="<?=$rt?>">0</span><div style="margin-top:12px"><?=$row('Pending',(int)($rx['pending']??0),$rt,'#fbbf24')?><?=$row('Dispensed',(int)($rx['dispensed']??0),$rt,'#2dd4bf')?></div></div>
<div class=wd><h4>IMAGING</h4><span class=big data-n="<?=$it?>">0</span><div style="margin-top:12px"><?=$row('Reported',(int)($img['reported']??0),$it,'#f472b6')?><?=$row('Queued',(int)($img['queued']??0),$it,'#fbbf24')?></div></div>
<div class=wd><h4>MINOR PROCEDURES</h4><span class=big data-n="<?=$pt2?>">0</span><div style="margin-top:12px"><?=$row('Completed',(int)($prc['done']??0),$pt2,'#2dd4bf')?><?=$row('Queued',(int)($prc['queued']??0),$pt2,'#fbbf24')?></div></div>
<div class=wd><h4>PATIENTS TODAY</h4><span class=big data-n="<?=$wait?>">0</span> still in the hospital<div style="margin-top:12px"><?=$row('Unpaid invoices',$unp,max($unp,1),'#f87171')?></div></div>
<div class=wd><h4>WARDS AND NBU</h4><span class=big data-n="<?=$inp?>">0</span> inpatients<div style="margin-top:10px;font-size:14px">Free beds: <b><?=max($beds,0)?></b><br>Babies in NBU: <b><?=$nbu?></b></div></div>
</div>
<div class=card><h3>Modules</h3><div class=g><?php foreach(modules() as $m){if(!can_mod($m)||$m[0]=='home')continue;echo '<'.($m[4]?'a href="'.$m[4].'"':'div').' class=mc'.($m[4]?'':' style="opacity:.55"').'><b>'.$m[2].'</b><div>'.e($m[1]).'<small>'.e($m[3]).($m[4]?'':' (coming soon)').'</small></div></'.($m[4]?'a':'div').'>';}?></div></div>
<script>var D=<?=json_encode(['days'=>array_values($days),'enc'=>array_values($enc),'col'=>array_map('array_values',$col),'dx'=>$dx])?>;
function bars(id,v,gold){var el=document.getElementById(id),m=Math.max.apply(null,v.concat([1])),h="";v.forEach(function(x,i){h+='<div><div class="bar'+(gold?' gold':'')+'" data-h="'+(x/m*100)+'" title="'+x.toLocaleString()+'"></div><small>'+D.days[i]+'</small></div>'});el.innerHTML=h;setTimeout(function(){el.querySelectorAll(".bar").forEach(function(b){b.style.height=b.dataset.h+"%"})},60)}
function cl(){var k=document.getElementById("cls").value,v=D.col[k];bars("cb",v,true);document.getElementById("ct").textContent=v.reduce(function(a,b){return a+b},0).toLocaleString(undefined,{minimumFractionDigits:2})}
function dl(){var r=D.dx[document.getElementById("dxs").value],h="";if(!r.length)h="<p style='opacity:.7'>No diagnoses yet.</p>";r.forEach(function(x){h+='<div class=dxr><span>'+x[0].replace(/</g,"&lt;")+'</span><span class=chip>'+x[1]+' cases</span></div>'});document.getElementById("dxl").innerHTML=h}
document.getElementById("cls").onchange=cl;document.getElementById("dxs").onchange=dl;bars("eb",D.enc,false);cl();dl();
document.querySelectorAll("[data-w]").forEach(function(i){setTimeout(function(){i.style.width=i.dataset.w+"%"},80)});
document.querySelectorAll("[data-n]").forEach(function(el){var t=+el.dataset.n,s=null;function f(ts){s=s||ts;var p=Math.min((ts-s)/1200,1);el.textContent=Math.round(t*p).toLocaleString();if(p<1)requestAnimationFrame(f)}requestAnimationFrame(f)});</script><?php foot();
